  "chunks": [
    {
      "chunk_type": "isnad",
      "arabic_text": "ابْنُ أَبِي عُمَيْرٍ وَ صَفْوَانُ بْنُ يَحْيَى جَمِيعاً عَنْ مُعَاوِيَةَ بْنِ عَمَّارٍ عَنْ أَبِي عَبْدِ اللَّهِ ( عليه السلام ) قَالَ",
      "translations": {
        "en": "Ibn Abi Umeyr and Safwan ibn Yahya, altogether, from Muawiya ibn Ammar, from Abu Abdillah (peace be upon him), who said:"
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "لَا تَأْكُلْ مِنَ الصَّيْدِ وَ أَنْتَ حَرَامٌ وَ إِنْ كَانَ الَّذِي أَصَابَهُ مُحِلٌّ وَ لَيْسَ عَلَيْكَ فِدَاءٌ مَا أَتَيْتَهُ بِجَهَالَةٍ إِلَّا الصَّيْدَ فَإِنَّ عَلَيْكَ فِيهِ الْفِدَاءَ بِجَهْلٍ كَانَ أَوْ بِعَمْدٍ.",
      "translations": {
        "en": "Do not eat from the prey while you are in Ihram, and even if the one who caught it is not in Ihram; and there is no ransom upon you for as long as you come to it out of ignorance, except for the hunting. Thus, upon you, with regards to it, is the ransom, whether it was out of ignorance or deliberate."
      }
    }
  ],
  "translations": {
    "en": {
      "summary": "This hadith establishes the ruling for a person in Ihram who eats game caught by another person. It clarifies that while the general rule is no ransom if the eater was ignorant, eating game specifically incurs a ransom (fidyah) regardless of whether the act was done out of ignorance or deliberately.",
      "seo_question": "What is the ruling on eating game caught by someone else while in Ihram?",
      "key_terms": {
        "الصَّيْد": "Game/Hunting prey",
        "حَرَام": "In the state of Ihram (ritual consecration for Hajj or Umrah)",
        "مُحِلٌّ": "One who is not in Ihram (permissible to eat)",
        "فِدَاء": "Ransom/Expiation (compensation for a ritual violation)",
        "جَهَالَة": "Ignorance",
        "عَمْد": "Deliberate/Intentional"
